-- PostgreSQL query.
-- Reference CSV was generated by executing equivalent logic on the SQLite validation DB.

WITH line_versions AS (
    SELECT
        l.*,
        h.supplier_id AS supplier_id,
        h.currency AS order_currency,
        h.order_dttm_msk AS order_dttm_msk,
        i.category,
        u.factor_to_base,
        ROW_NUMBER() OVER (
            PARTITION BY l.order_id, l.line_no
            ORDER BY l.updated_at DESC, l.source_row_no DESC
        ) AS rn
    FROM core_po_line_version l
    JOIN core_po_header h
        ON h.order_id = l.order_id
    LEFT JOIN core_dim_item i
        ON i.item_id = l.item_id
    LEFT JOIN core_dim_uom u
        ON u.uom_code = l.uom_code
),
selected AS (
    SELECT *
    FROM line_versions
    WHERE rn = 1
      AND LOWER(COALESCE(status, '')) <> 'cancelled'
      AND planned_delivery_date IS NOT NULL
      AND factor_to_base > 0
),
valued AS (
    SELECT
        s.*,
        qty * price * (
            CASE
                WHEN UPPER(order_currency) IN ('RUB', 'RUR') THEN 1.0
                ELSE fx.rate_to_rub
            END
        ) AS amount_rub
    FROM selected s
    LEFT JOIN core_dim_fx_rate fx
        ON fx.rate_date::date = s.order_dttm_msk::date
       AND fx.currency = s.order_currency
),
supplier_category AS (
    SELECT
        COALESCE(category, 'UNKNOWN') AS category,
        supplier_id,
        SUM(amount_rub) AS turnover_rub
    FROM valued
    WHERE amount_rub IS NOT NULL
    GROUP BY COALESCE(category, 'UNKNOWN'), supplier_id
),
shares AS (
    SELECT
        *,
        SUM(turnover_rub) OVER (
            PARTITION BY category
        ) AS category_turnover_rub,
        1.0 * turnover_rub
            / NULLIF(
                SUM(turnover_rub) OVER (PARTITION BY category),
                0
            ) AS share
    FROM supplier_category
),
ranked AS (
    SELECT
        *,
        SUM(share) OVER (
            PARTITION BY category
            ORDER BY turnover_rub DESC, supplier_id
            ROWS UNBOUNDED PRECEDING
        ) AS cumulative_share,
        ROW_NUMBER() OVER (
            PARTITION BY category
            ORDER BY turnover_rub DESC, supplier_id
        ) AS supplier_rank
    FROM shares
),
coverage AS (
    SELECT
        category,
        MIN(
            CASE
                WHEN cumulative_share >= 0.8 THEN supplier_rank
            END
        ) AS suppliers_to_80_pct
    FROM ranked
    GROUP BY category
)
SELECT
    r.category,
    r.supplier_id,
    ROUND(r.turnover_rub::numeric, 2) AS supplier_turnover_rub,
    ROUND(r.category_turnover_rub::numeric, 2) AS category_turnover_rub,
    ROUND((100 * r.share)::numeric, 2) AS share_pct,
    ROUND((100 * r.cumulative_share)::numeric, 2) AS cumulative_share_pct,
    c.suppliers_to_80_pct
FROM ranked r
JOIN coverage c USING (category)
ORDER BY r.category, r.supplier_rank;